    public static async Task VerifyAsync(string outputDirectory,string repositoryRoot,string? libraryRoot=null)
    {
        var fixture=Path.Combine(Path.GetFullPath(outputDirectory),"studio-header-refinement-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);var receipt=new Receipt{Fixture=fixture};
        try{await RunStaAsync(()=>{LoadResources(repositoryRoot);foreach(var size in new[]{new Size(1280,940),new Size(640,940)})VerifySize(size,libraryRoot,fixture,receipt);return Task.CompletedTask;});receipt.Passed=true;}
        catch(Exception error){receipt.Failure=error.ToString();throw;}
        finally{await File.WriteAllTextAsync(Path.Combine(fixture,"studio-header-refinement-ui-verification.json"),JsonSerializer.Serialize(receipt,new JsonSerializerOptions{WriteIndented=true}));}
        Console.WriteLine($"STUDIO_HEADER_REFINEMENT_UI_OK|checks={receipt.Assertions.Count}|renders={receipt.Renders.Count}|fixture={fixture}");
    }
